#!/usr/bin/env bash
# ICBAR photo downloader (self-contained, generated by crawler.py)
# Photos are only downloaded locally. No SQLite/Python required.
set -Eeuo pipefail

OUTPUT_DIR="${OUTPUT_DIR:-$(pwd)/icbar_images}"
JOBS="${JOBS:-6}"
DELAY="${DELAY:-0.3}"

case "$JOBS" in ''|*[!0-9]*) echo 'JOBS must be an integer' >&2; exit 2;; esac
if (( JOBS < 1 || JOBS > 16 )); then echo 'JOBS must be between 1 and 16' >&2; exit 2; fi
command -v curl >/dev/null || { echo 'curl is required' >&2; exit 2; }
command -v xargs >/dev/null || { echo 'xargs is required' >&2; exit 2; }

fetch_photo() {
  local row="$1" slug url rel dest part mime
  IFS=$'\t' read -r slug url rel <<< "$row"
  [[ "$url" == https://icbar.ir/* || "$url" == http://127.0.0.1:*/* ]] || { echo "Rejected URL: $url" >&2; return 1; }
  [[ "$rel" == photos/* && "$rel" != *'..'* ]] || { echo 'Rejected output path' >&2; return 1; }
  dest="$OUTPUT_DIR/$rel"
  if [[ -s "$dest" ]]; then return 0; fi
  mkdir -p "$(dirname "$dest")"
  part="${dest}.part"
  # curl -C - resumes partially downloaded files; failed downloads remain .part.
  # If the server does not implement range requests, fall back to a clean transfer.
  if ! curl --location --fail --silent --show-error --retry 4 --retry-delay 2 \
       --retry-all-errors --connect-timeout 20 --max-time 180 \
       -A 'Mozilla/5.0 (compatible; ICBAR-Backup/1.0)' \
       -H 'Referer: https://icbar.ir/' --continue-at - \
       --output "$part" "$url"; then
    rm -f "$part"
    curl --location --fail --silent --show-error --retry 4 --retry-delay 2 \
         --retry-all-errors --connect-timeout 20 --max-time 180 \
         -A 'Mozilla/5.0 (compatible; ICBAR-Backup/1.0)' \
         -H 'Referer: https://icbar.ir/' --output "$part" "$url" || return 1
  fi
  [[ -s "$part" ]] || { rm -f "$part"; return 1; }
  # Avoid silently storing an HTML error page as a photo.
  if command -v file >/dev/null; then
    mime="$(file -b --mime-type "$part")"
    case "$mime" in image/*) ;; *) echo "Not image ($mime): $url" >&2; rm -f "$part"; return 1;; esac
  fi
  mv -f "$part" "$dest"
  [[ "$DELAY" == 0 ]] || sleep "$DELAY"
}
export OUTPUT_DIR DELAY
export -f fetch_photo

